(() => {
    const g = __rhf.game;
    g.state.settings.autoQuality = false;
    g.setQuality('low');
    g.bears.directorT = 1e9;
    g.env.timeScale = 0;
    g.hud.firstShown = -1000;
    __rhf.god(true);
    window.__until = async (fn, ms = 240000) => {
      const t0 = performance.now();
      while (performance.now() - t0 < ms) {
        const r = fn();
        if (r) return r;
        await new Promise((q) => setTimeout(q, 200));
      }
      return null;
    };
    // step the bear system in fixed 50 ms ticks, recording every state a
    // bear passes through
    window.__sim = (b, sec) => {
      const seen = new Set([b.state]);
      for (let t = 0; t < sec; t += 0.05) {
        g.bears.update(0.05);
        seen.add(b.state);
      }
      return [...seen].join(' > ');
    };
    // a grizzly, sent to stand at a distance from the player on flat ground
    window.__placeBear = (b, dist) => {
      const W = g.world;
      const P = g.player.pos;
      for (let a = 0; a < 64; a++) {
        const ang = (a / 64) * Math.PI * 2;
        const x = P.x + Math.sin(ang) * dist;
        const z = P.z + Math.cos(ang) * dist;
        if (W.waterAt(x, z) || W.slopeAt(x, z) > 0.3) continue;
        b.x = x;
        b.z = z;
        b.y = W.heightAt(x, z);
        b.tx = P.x;
        b.tz = P.z;
        b.t = 30;
        b.dead = false;
        b.hp = b.kind === 'black' ? 150 : 240;
        return true;
      }
      return false;
    };
    return 'set up';
  })()

(() => {
    const g = __rhf.game;
    const B = g.bears.bears;
    const kinds = {};
    for (const b of B) kinds[b.kind] = (kinds[b.kind] || 0) + 1;
    const herd = g.wildlife.herds.blackbear;
    return 'bears: ' + Object.entries(kinds).map(([k, n]) => n + ' ' + k).join(', ') + '; black bear herd model ' + (herd ? 'ready' : 'MISSING') + '; black bears in the wildlife list ' + g.wildlife.animals.filter((a) => a.species === 'blackbear').length;
  })()

(() => {
    const g = __rhf.game;
    __rhf.tp('landing');
    g.state.cooler = [];
    const b = g.bears.bears.find((x) => x.kind === 'grizzly');
    window.__griz = b;
    __placeBear(b, 20);
    b.state = 'roam';
    const roam = __sim(b, 20);
    __placeBear(b, 30);
    b.state = 'stalk';
    const stalk = __sim(b, 6);
    return 'empty cooler: a roaming grizzly 20 m away went ' + roam + '; a stalking one went ' + stalk + '; threat ' + !!g.bears.threat + ', health ' + Math.round(g.state.health);
  })()

(() => {
    const g = __rhf.game;
