(() => {
    const g = __rhf.game;
    const b = __griz;
    g.bears.threat = null;
    __placeBear(b, 20);
    b.state = 'roam';
    g.state.cooler = [{ species: 'sockeye', weight: 3.1, length: 60, value: 40, legend: false, name: 'Sockeye Salmon' }];
    let seen = '';
    for (let t = 0; t < 10 && b.state !== 'alert'; t += 0.05) g.bears.update(0.05);
    seen = 'alerted ' + (b.state === 'alert');
    g.state.cooler = [];
    const after = __sim(b, 6);
    return seen + '; the fish sold mid-alert: it went ' + after + '; threat ' + !!g.bears.threat;
  })()

(() => {
    const g = __rhf.game;
    const b = g.bears.bears.find((x) => x.kind === 'black');
    window.__black = b;
    g.bears.threat = null;
    g.state.cooler = [];
    __placeBear(b, 15);
    b.state = 'roam';
    const calm = __sim(b, 10);
    g.state.cooler = [{ species: 'sockeye', weight: 3.1, length: 60, value: 40, legend: false, name: 'Sockeye Salmon' }];
    __placeBear(b, 15);
    b.state = 'roam';
    b.bluff = false;
    const smell = __sim(b, 6);
    const st = b.state;
    b.hp -= 30;
    g.bears.onHit(b, false);
    return 'black bear, empty cooler: ' + calm + ' | with a fish: ' + smell + ' | after an arrow in a ' + st + ': ' + b.state + ', threat ' + !!g.bears.threat;
  })()

