(async () => {
    const g = __rhf.game;
    const H = g.hunting;
    const b = __griz;
    g.bears.threat = null;
    g.state.cooler = [{ species: 'sockeye', weight: 3.1, length: 60, value: 40, legend: false, name: 'Sockeye Salmon' }];
    g.state.gear.arrow = 'whistler';
    __placeBear(b, 30);
    b.state = 'charge';
    b.t = 30;
    b.bluff = false;
    b.cfg = { ...b.cfg };
    b.cfg.run = 0.001;
    g.bears.threat = b;
    // shoot 4 m wide of the bear: a near miss
    const P = g.player.pos;
    const dx = b.x - P.x;
    const dz = b.z - P.z;
    const d = Math.hypot(dx, dz);
    const side = { x: dz / d, z: -dx / d };
    const tx = b.x + side.x * 4;
    const tz = b.z + side.z * 4;
    g.player.yaw = Math.atan2(-(tx - P.x), -(tz - P.z));
    g.player.pitch = Math.atan2(b.y + 1 - (P.y + 1.7), d) + 0.03;
    const before = g.state.arrowsLeft('whistler');
    __rhf.hold('primary', true);
    // the software renderer draws a frame every few seconds: be patient
    const drawn = await __until(() => H.draw >= 1, 240000);
    g.player.yaw = Math.atan2(-(tx - P.x), -(tz - P.z));
    __rhf.hold('primary', false);
    await __until(() => b.state === 'flee' || (H.arrows.length > 0 && H.arrows.every((a) => a.stuck)), 120000);
    if (!drawn) return 'the bow never reached full draw';
    return 'whistler loosed (' + before + ' > ' + g.state.arrowsLeft('whistler') + '): bear ' + b.state + ', threat ' + !!g.bears.threat + ', hp ' + Math.round(b.hp);
  })()

(() => {
    const g = __rhf.game;
    const s = g.state;
    const j = s.toJSON();
    j.gear.arrows = 7;
    delete j.gear.quiver;
    delete j.gear.arrow;
    const raw = JSON.stringify(j);
    const key = Object.keys(localStorage).find((k) => k.startsWith('rubenHotrodFishing')) || 'rubenHotrodFishing.save';
    const old = localStorage.getItem(key);
    localStorage.setItem(key, raw);
    const ok = s.load();
    const r = 'old save loaded ' + ok + ': quiver ' + JSON.stringify(s.gear.quiver) + ', on the string ' + s.gear.arrow + ', plain count gone ' + (s.gear.arrows === undefined);
    if (old !== null) localStorage.setItem(key, old);
    return r;
  })()
